# --- Tests for MorphogenesisEngine ---

class TestMorphogenesisEngine:
    def test_init(self):
        engine = MorphogenesisEngine(model_name='test_model')
        assert engine.model_name == 'test_model'

    def test_morph_genome_topology_deep_copy_isolation(self, company_a):
        original_company_a = company_a.copy()
        engine = MorphogenesisEngine()
        child = engine.morph_genome_topology(company_a, "no_op_mutation", 2, "child_A")

        assert child is not company_a
        assert child.company_id == "child_A"
        assert child.generation == 2
        assert child.parent_ids == ["company_A"]
        assert "no_op_mutation" in child.mutation_history

        # Verify parent_a is unchanged
        assert company_a == original_company_a
        assert company_a.code_overlays == original_company_a.code_overlays
        assert company_a.departments == original_company_a.departments
        assert company_a.ceo == original_company_a.ceo

        # Verify child.code_overlays is an independent copy
        assert child.code_overlays is not company_a.code_overlays
        assert child.code_overlays == company_a.code_overlays

    def test_morph_genome_topology_lineage(self, company_a):
        engine = MorphogenesisEngine()
        child = engine.morph_genome_topology(company_a, "test_mutation", 3, "new_child_id")

        assert child.company_id == "new_child_id"
        assert child.generation == 3
        assert child.parent_ids == [company_a.company_id]
        assert "test_mutation" in child.mutation_history

    def test_morph_genome_topology_tool_enablement_trivial(self, company_a):
        # Current no-op morph trivially satisfies this as no new agents are spawned.
        # We check that existing agents' tools_enabled status is preserved.
        engine = MorphogenesisEngine()
        child = engine.morph_genome_topology(company_a, "no_op", 2, "child_A")

        for original_dept, child_dept in zip(company_a.departments, child.departments):
            for original_agent, child_agent in zip(original_dept.agents, child_dept.agents):
                assert original_agent.tools_enabled == child_agent.tools_enabled

    def test_morph_genome_topology_protected_pods_min_two_depts_pass(self, company_a_minimal):
        engine = MorphogenesisEngine()
        # company_a_minimal has 2 departments, should pass the invariant check
        child = engine.morph_genome_topology(company_a_minimal, "no_op", 2, "child_A_min")
        assert len(child.departments) >= 2

    def test_morph_genome_topology_protected_pods_min_two_depts_fail(self, company_single_dept):
        engine = MorphogenesisEngine()
        # company_single_dept has 1 department. The no-op morph will return a child with 1 department.
        # This should trigger the AssertionError.
        with pytest.raises(AssertionError, match="Child genome must retain at least 2 departments."):
            engine.morph_genome_topology(company_single_dept, "no_op", 2, "child_single_dept")

    def test_morph_genome_topology_protected_pods_present_in_child(self, company_a_minimal):
        engine = MorphogenesisEngine()
        child = engine.morph_genome_topology(company_a_minimal, "no_op", 2, "child_A_min")

        # Check that protected departments are still present (due to no-op)
        child_dept_ids = {d.dept_id for d in child.departments}

        assert "dept_systems_eng" in child_dept_ids
        assert "dept_qa_redteam" in child_dept_ids
        # This test confirms the no-op doesn't prune, satisfying the invariant for this implementation.


