        if original_product_ux.agents: # Check if agents exist before asserting
            assert child_product_ux.agents[0] is not original_product_ux.agents[0]

    def test_recombine_department_alignment_asymmetric_counts_same_category(self, company_a, dept_systems_eng_a, dept_systems_eng_b, sample_manager_a, sample_manager_b, sample_agent_a, sample_agent_b, sample_agent_c):
        # Parent A has 2 systems_eng depts (dept_systems_eng_a, dept_ai_acceleration_a)
        # Parent B has 1 systems_eng dept (dept_systems_eng_b)

        # Create a custom company_a with two systems_eng departments
        custom_company_a = company_a.copy()
        custom_company_a.departments = [
            dept_systems_eng_a.copy(), # systems_eng
            dept_systems_eng_a.copy(), # another systems_eng
            company_a.departments[1].copy(), # qa_redteam
        ]
        custom_company_a.departments[1].dept_id = "dept_systems_eng_extra_a"
        custom_company_a.departments[1].name = "Advanced Systems"

        # Create a custom company_b with one systems_eng department
        custom_company_b = company_b.copy()
        custom_company_b.departments = [
            dept_systems_eng_b.copy(), # systems_eng
            company_b.departments[1].copy(), # qa_redteam
        ]

        engine = StructuralCrossoverEngine()
        child = engine.recombine(custom_company_a, custom_company_b, "child_asym", 2)

        systems_eng_depts = [d for d in child.departments if classify_department_role(d) == "systems_eng"]
        assert len(systems_eng_depts) == 2 # One recombined, one carried over from A

        # First systems_eng dept should be recombined
        recombined_dept = systems_eng_depts[0]
        assert recombined_dept.dept_id == dept_systems_eng_a.dept_id # Base from A

        # Manager recombination
        # Parent A manager temp: 0.75, traits: ["strategic", "innovative"]
        # Parent B manager temp: 0.85, traits: ["operational", "detail-oriented"]
        assert recombined_dept.manager.temperature == 0.8

        # Agent interleaving
        # Parent A agents: [agent_a, agent_b]
        # Parent B agents: [agent_c]
        expected_agent_ids_recombined = ["agent_a", "agent_c", "agent_b"]
        assert [a.agent_id for a in recombined_dept.agents] == expected_agent_ids_recombined

        # Second systems_eng dept should be carried over from A
        carried_over_dept = systems_eng_depts[1]
        assert carried_over_dept.dept_id == "dept_systems_eng_extra_a"
        assert carried_over_dept.name == "Advanced Systems"
        assert carried_over_dept.manager.manager_id == sample_manager_a.manager_id
        assert [a.agent_id for a in carried_over_dept.agents] == [sample_agent_a.agent_id, sample_agent_b.agent_id]

